  if (route.startsWith('/app/') && window.__authStatus === 'loading') { app.innerHTML = `<main class="auth-page"><section class="auth-card"><div class="mentor-orb">✦</div><h1>Đang mở hành trình của bạn</h1><p>BeyondU đang tải dữ liệu đã lưu trên thiết bị…</p></section></main>`; return; }
